// Scene descriptions: captions for the keyframes the worker extracted (first frame + scene cuts),
// generated by a vision-capable Ollama model. By default this is the same multimodal model as the
// summary, so an 8 GB GPU never has to swap models between the two steps.
import fs from 'node:fs';
import path from 'node:path';
import { isInside } from '../storage/paths.js';

const CAPTION_PROMPT = [
  'Describe this video frame in one or two factual sentences:',
  'the setting, the people (what they are doing) and important visible objects or text.',
  'Do not guess identities. Do not start with "The image shows".',
].join(' ');

/**
 * Adds `caption` to keyframes of `analysis` (mutates and returns it).
 * @param {{ ollama: import('./ollama.js').OllamaService, cfg: object, analysis: object, framesRoot: string,
 *           signal?: AbortSignal, onProgress?: (p: number) => void, logger: import('pino').Logger }} params
 */
export async function describeKeyframes({ ollama, cfg, analysis, framesRoot, signal, onProgress = () => {}, logger }) {
  const keyframes = (analysis.frames ?? []).filter((f) => f.keyframe && !f.caption).slice(0, cfg.vision.maxFrames);
  let done = 0;
  for (const frame of keyframes) {
    const file = path.resolve(framesRoot, frame.keyframe);
    if (!isInside(path.resolve(framesRoot), file)) continue; // never read outside the frames directory
    let image;
    try {
      image = await fs.promises.readFile(file);
    } catch {
      logger.warn({ keyframe: frame.keyframe }, 'keyframe missing; skipping caption');
      continue;
    }
    const { text } = await ollama.chat({
      model: cfg.vision.model,
      messages: [{ role: 'user', content: CAPTION_PROMPT, images: [image.toString('base64')] }],
      // Same num_ctx as the summary: changing it would make Ollama reload the model.
      options: { temperature: 0, num_ctx: cfg.numCtx, num_predict: 120 },
      think: false,
      signal,
    });
    frame.caption = text.replace(/\s+/g, ' ').trim().slice(0, 400);
    onProgress(++done / keyframes.length);
  }
  return analysis;
}
